import semver from 'semver';

import { version as currentVersion } from '../version';

import { Module, API } from '../index';

export interface Version {
  version: string;
  info?: { plain: string };
  [key: string]: any;
}

export interface UnknownEntries {
  [key: string]: {
    [key: string]: any;
  };
}

export interface Versions {
  latest?: Version;
  next?: Version;
  current?: Version;
}

export interface SubState {
  versions: Versions & UnknownEntries;
  lastVersionCheck: number;
  dismissedVersionNotification: undefined | string;
}

// Grab versions from the DOM, which is populated at build time by the server. This means
// we do not have to make any HTTP requests at runtime to know about available updates.
const getVersionCheckData = (): Versions => {
  try {
    return { ...(JSON.parse(VERSIONCHECK).data || {}) };
  } catch (e) {
    return {};
  }
};

export interface SubAPI {
  getCurrentVersion: () => Version;
  getLatestVersion: () => Version;
  versionUpdateAvailable: () => boolean;
}

export default function({ store, mode }: Module) {
  const { dismissedVersionNotification } = store.getState();

  const state = {
    versions: {
      ...getVersionCheckData(),
      current: {
        version: currentVersion,
      },
    },
    dismissedVersionNotification,
  };

  const api: SubAPI = {
    getCurrentVersion: () => {
      const {
        versions: { current },
      } = store.getState();
      return current;
    },
    getLatestVersion: () => {
      const {
        versions: { latest, next, current },
      } = store.getState();
      if (current && semver.prerelease(current.version) && next) {
        return latest && semver.gt(latest.version, next.version) ? latest : next;
      }
      return latest;
    },
    versionUpdateAvailable: () => {
      const latest = api.getLatestVersion();
      const current = api.getCurrentVersion();

      if (latest) {
        if (!latest.version) {
          return true;
        }
        if (!current.version) {
          return true;
        }

        const onPrerelease = !!semver.prerelease(latest.version);

        const actualCurrent = semver.prerelease(current.version)
          ? `${semver.major(current.version)}.${semver.minor(current.version)}.${semver.patch(
              current.version
            )}`
          : current.version;

        const diff = semver.diff(actualCurrent, latest.version);

        return (
          semver.gt(latest.version, actualCurrent) &&
          !onPrerelease &&
          (diff === 'minor' || diff === 'major')
        );
      }
      return false;
    },
  };

  // Refresh the notification, but don't do it until the rest of the app is ready
  const initModule = async () => {
    const { latest } = getVersionCheckData();

    if (
      latest &&
      api.versionUpdateAvailable() &&
      mode !== 'production' &&
      latest.version !== dismissedVersionNotification
    ) {
      api.addNotification({
        id: 'update',
        link: '/settings/about',
        content: {
          headline: `Storybook ${latest.version} is available!`,
          subHeadline: `Your current version is: ${currentVersion}`,
        },
        icon: { name: 'book' },
        onClear() {
          store.setState(
            { dismissedVersionNotification: latest.version },
            { persistence: 'permanent' }
          );
        },
      });
    }
  };

  return {
    init: async ({ api: fullApi }: API) => {
      const { latest } = getVersionCheckData();

      if (
        latest &&
        api.versionUpdateAvailable() &&
        mode !== 'production' &&
        latest.version !== dismissedVersionNotification
      ) {
        fullApi.addNotification({
          id: 'update',
          link: '/settings/about',
          content: `🎉 Storybook ${latest.version} is available!`,
          onClear() {
            store.setState(
              { dismissedVersionNotification: latest.version },
              { persistence: 'permanent' }
            );
          },
        });
      }
    },
    state,
    api,
